using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public class DiscountAcceptanceTests
{
    private static int ChargedFor(int subtotalCents, LoyaltyTier tier) =>
        new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier))
            .TotalCents;

    // Bronze customer is charged the Bronze price for a basket
    [Fact]
    public void S1_BronzeCustomerIsCharged9500CentsForSubtotal10000()
    {
        Assert.Equal(9500, ChargedFor(10000, LoyaltyTier.Bronze));
    }

    // Silver customer is charged the Silver price for a basket
    [Fact]
    public void S2_SilverCustomerIsCharged9000CentsForSubtotal10000()
    {
        Assert.Equal(9000, ChargedFor(10000, LoyaltyTier.Silver));
    }

    // Gold customer is charged the Gold price for a basket
    [Fact]
    public void S3_GoldCustomerIsCharged8500CentsForSubtotal10000()
    {
        Assert.Equal(8500, ChargedFor(10000, LoyaltyTier.Gold));
    }

    // Bronze customer is charged a whole cent amount for a very small basket
    [Fact]
    public void S4_BronzeCustomerIsCharged7CentsForSubtotal7()
    {
        Assert.Equal(7, ChargedFor(7, LoyaltyTier.Bronze));
    }
}

